fn cube_root(n: u8) -> u8 {
    // We promote to u16 to avoid overflow when cubing.
    let n16 = n as u16;
    let mut r = 0u8;
    // Increase r while (r+1)^3 is still ≤ n.
    // Since n ≤ 255, r will never exceed 6 in practice,
    // and (r+1)^3 ≤ 343 fits comfortably in u16.
    while (r as u16 + 1).pow(3) <= n16 {
        r += 1;
    }
    r
}

